Q: Multiline label for SwiftUI Picker SegmentedPickerStyle A: <p>Here is a way to get 2-line labels and still maintain Apple's treatment for ios26.  Basically render text to an image and use the image.  Also, it uses the maximum control size.  If you try to go to more than 2 lines, text will get squished/distorted.  Uses ImageRenderer in extension to Image.</p>
<pre><code>import SwiftUI

extension Image {
    @MainActor
    static func simpleTextRender(text: String, alignment: TextAlignment = .center) -&gt; Image? {
        let renderer = ImageRenderer(content: SimpleTextRendererView(text: text))

        if let uiImage = renderer.uiImage {
            let renderedImage = Image(uiImage: uiImage)
            return renderedImage
        }
        return nil
    }
}

struct SimpleTextRendererView: View {
    // Used in part of generating 2-line text views for pickers
    let text: String
    let alignment: TextAlignment = .center // Allow user to change text alignment of label. Default to center.

    var body: some View {
        Text(text).multilineTextAlignment(alignment)
    }
}

enum Direction: Int, CaseIterable { case case1, case2, case3 }
extension Direction {
    var title: String {
        // Note: embed newline in text where needed.
        switch self {
            case .case1: return &quot;3D\nFahrtrichtung&quot;
            case .case2: return &quot;2D\nFahrtrichtung&quot;
            case .case3: return &quot;2D\nNordweisend&quot;
        }
    }
    var image: Image {
        return Image.simpleTextRender(text: self.title) ?? Image(systemName: &quot;questionmark&quot;)  // Fallback never used
    }
}

struct ContentView: View {
    @State private var direction: Direction = .case1
    var body: some View {
        Picker(&quot;Direction&quot;, selection: $direction) {
            ForEach(Direction.allCases, id: \.self) { type in
                type.image.tag(type)
            }
        }
        .pickerStyle(.segmented)
        .controlSize(.extraLarge) // Give maximumu height
    }
}
</code></pre>
